FROM `indicators`.`tmp_exclude_ids`)))))) AND (((`hid0101_cache_his_dhcapp_sqluser`.`a`.`paadm_type` = 'I') AND (`hid0101_cache_his_dhcapp_sqluser`.`a`.`paadm_visitstatus` != 'C')) AND (`hid0101_cache_his_dhcapp_sqluser`.`a`.`paadm_dischgdate` IS NOT NULL))) AND ((CAST(`hid0101_cache_his_dhcapp_sqluser`.`a`.`paadm_dischgdate` AS VARCHAR)) = (substring(CAST((current_timestamp()) AS VARCHAR), 1, 10)))
