CREATE MATERIALIZED VIEW `indicators`.`currentryxz_v3` (`hosp_code`, `paadm_depcode_dr`, `ctloc_code`, `ctloc_desc`, `ward_code`, `ward_desc`, `ssryresult`, `lastupdatedttm`)
