)
AS SELECT 'HID0101' AS `hosp_code`, `hid0101_cache_his_dhcapp_sqluser`.`a`.`paadm_depcode_dr`, `hid0101_cache_his_dhcapp_sqluser`.`c`.`ctloc_code`, `hid0101_cache_his_dhcapp_sqluser`.`c`.`ctloc_desc`, `hid0101_cache_his_dhcapp_sqluser`.`pac_ward`.`ward_code`, `hid0101_cache_his_dhcapp_sqluser`.`pac_ward`.`ward_desc`, count(DISTINCT `hid0101_cache_his_dhcapp_sqluser`.`a`.`paadm_admno`) AS `ssryresult`, current_timestamp() AS `lastupdatedttm`
