FROM `hid0123_cache_his_dhcapp_sqluser`.`dhc_patbilldetails` AS `billdet` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`dhc_patbillorder` AS `pbo` ON `hid0123_cache_his_dhcapp_sqluser`.`billdet`.`pbd_pbo_parref` = `hid0123_cache_his_dhcapp_sqluser`.`pbo`.`pbo_rowid` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`dhc_patientbill` AS `bill` ON `hid0123_cache_his_dhcapp_sqluser`.`bill`.`pb_rowid` = `hid0123_cache_his_dhcapp_sqluser`.`pbo`.`pbo_pb_parref` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`pa_adm` AS `adm` ON `hid0123_cache_his_dhcapp_sqluser`.`bill`.`pb_adm_dr` = `hid0123_cache_his_dhcapp_sqluser`.`adm`.`paadm_rowid` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`dhc_taritem` AS `taritem` ON `hid0123_cache_his_dhcapp_sqluser`.`billdet`.`pbd_tari_dr` = `hid0123_cache_his_dhcapp_sqluser`.`taritem`.`tari_rowid` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`dhc_taremccate` AS `taremc` ON `hid0123_cache_his_dhcapp_sqluser`.`taritem`.`tari_emccate` = `hid0123_cache_his_dhcapp_sqluser`.`taremc`.`tarec_rowid` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`dhc_tarec` AS `tarec` ON `hid0123_cache_his_dhcapp_sqluser`.`tarec`.`tartec_rowid` = `hid0123_cache_his_dhcapp_sqluser`.`taremc`.`tarec_tartec_dr` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`oe_orditem` AS `oeori` ON `hid0123_cache_his_dhcapp_sqluser`.`oeori`.`oeori_rowid` = `hid0123_cache_his_dhcapp_sqluser`.`pbo`.`pbo_oeori_dr` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`ct_loc` AS `ctloc` ON `hid0123_cache_his_dhcapp_sqluser`.`oeori`.`oeori_orddept_dr` = `hid0123_cache_his_dhcapp_sqluser`.`ctloc`.`ctloc_rowid` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`ct_loc` AS `ctlocjs` ON `hid0123_cache_his_dhcapp_sqluser`.`oeori`.`oeori_recdep_dr` = `hid0123_cache_his_dhcapp_sqluser`.`ctlocjs`.`ctloc_rowid` LEFT OUTER JOIN `hid0123_cache_his_dhcapp_sqluser`.`ct_loc` AS `ctlocjzks` ON `hid0123_cache_his_dhcapp_sqluser`.`adm`.`paadm_depcode_dr` = `hid0123_cache_his_dhc