CREATE MATERIALIZED VIEW `indicators`.`mzssxz_indicators_v3` (`hosp_code`, `ctloc_desc`, `ctloc_code`, `questatedr`, `paadm_type`, `ghl`, `lastupdatedttm`)
COMMENT "实时就诊挂号"
DISTRIBUTED BY HASH(`hosp_code`)
REFRESH ASYNC EVERY(INTERVAL 180 SECOND)
PROPERTIES (
"replicated_storage" = "true",
"replication_num" = "3",
"storage_medium" = "HDD"
)
