USE indicators;

-- 1）列出 indicators 库下全部异步物化视图（名称、刷新状态、行数等）
SHOW MATERIALIZED VIEWS FROM indicators;

-- 2）仅查 _v3 / _v2 物化视图
SHOW MATERIALIZED VIEWS FROM indicators
WHERE NAME LIKE '%_v3' OR NAME LIKE '%_v2';

-- 3）information_schema 明细（含最近刷新时间、状态、错误信息）
SELECT
    TABLE_SCHEMA,
    TABLE_NAME,
    REFRESH_TYPE,
    IS_ACTIVE,
    LAST_REFRESH_STATE,
    LAST_REFRESH_START_TIME,
    LAST_REFRESH_FINISHED_TIME,
    LAST_REFRESH_ERROR_MESSAGE,
    ROWS
FROM information_schema.materialized_views
WHERE TABLE_SCHEMA = 'indicators'
ORDER BY TABLE_NAME;

-- 4）按院区抽样（含 HID0122/HID0123/HID0124 公卫）
SELECT 'currentcyxz_v3' AS mv, hosp_code, count(*) AS cnt FROM indicators.currentcyxz_v3 GROUP BY hosp_code
UNION ALL
SELECT 'currentryxz_v3', hosp_code, count(*) FROM indicators.currentryxz_v3 GROUP BY hosp_code
UNION ALL
SELECT 'currentzyxz_v3', hosp_code, count(*) FROM indicators.currentzyxz_v3 GROUP BY hosp_code
UNION ALL
SELECT 'currtime_income_v3', hosp_code, count(*) FROM indicators.currtime_income_v3 GROUP BY hosp_code
UNION ALL
SELECT 'mzssxz_indicators_v3', hosp_code, count(*) FROM indicators.mzssxz_indicators_v3 GROUP BY hosp_code;

